import hashlib
def tid(t): return hashlib.md5(t[1].encode()).hexdigest()[:8]
def related(path,r,cat=None):
    import random
    rnd=random.Random(path); pool=[t for t in T if t[6] is None or t[6]!=path.replace("index.html","")]
    same=[t for t in pool if t[0]==cat]; other=[t for t in pool if t[0]!=cat]; rnd.shuffle(same); rnd.shuffle(other)
    pick=(same[:3]+other)[:6]
    return '<section class="related"><h2>🔗 Related trends</h2><div class="grid">'+"".join(card(t,r) for t in pick)+'</div></section>'
def share(url,title):
    u=quote(url,safe=""); ti=quote(title,safe="")
    return f'<div class="share"><b>Share:</b> <a href="https://x.com/intent/post?url={u}&text={ti}" {EXT}>X</a><a href="https://www.facebook.com/sharer/sharer.php?u={u}" {EXT}>Facebook</a><a href="https://www.reddit.com/submit?url={u}&title={ti}" {EXT}>Reddit</a><a href="https://wa.me/?text={ti}%20{u}" {EXT}>WhatsApp</a><a href="https://www.threads.net/intent/post?text={ti}%20{u}" {EXT}>Threads</a><button type="button" class="js-share" data-url="{url}" data-title="{esc(title)}" hidden>Copy / share</button></div>'

